import type { PieceKind } from '../core/types';
import spriteSheetUrl from '../assets/sprites.png';

/** Atlas cell size in px; generated by scripts/build-sprites.mjs. */
export const SPRITE_CELL = 64;

/**
 * Atlas cell (column, row) per piece kind. Sylph uses the sheet's djinni art, serpent its basilisk art.
 * Elementals have no cell: the arena draws them procedurally.
 */
const CELLS: Readonly<Partial<Record<PieceKind, readonly [number, number]>>> = {
  wizard: [0, 0], unicorn: [1, 0], knight: [2, 0], archer: [3, 0], valkyrie: [4, 0], golem: [5, 0], sylph: [6, 0], phoenix: [7, 0],
  sorceress: [0, 1], dragon: [1, 1], shapeshifter: [2, 1], troll: [3, 1], goblin: [4, 1], banshee: [5, 1], manticore: [6, 1], serpent: [7, 1],
};

/** Which way each picture faces on the sheet: 1 = right. Front-facing art counts as right. */
export const nativeHeading = (kind: PieceKind): 1 | -1 => (kind === 'dragon' ? -1 : 1);

export function spriteCell(kind: PieceKind): { sx: number; sy: number } | null {
  const cell = CELLS[kind];
  return cell ? { sx: cell[0] * SPRITE_CELL, sy: cell[1] * SPRITE_CELL } : null;
}

/** Loads the sprite sheet; resolves to null if it fails so callers can fall back to glyphs. */
export const loadSpriteSheet = (): Promise<HTMLImageElement | null> =>
  new Promise((resolve) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => resolve(null);
    img.src = spriteSheetUrl;
  });
